/**
 * Wire-shape types for antman's search-table endpoints.
 *
 * Mirrors antman's OpenAPI schemas under `/v1/aspects/{aspectId}/...`
 * (the OpenAPI surface itself drops the `/v1` context path, but the
 * deployed routes only respond on the prefixed form — see the client
 * module for details):
 *   - AspectSearchTableSnowflakeCreateRequest (POST /v1/aspects/{aspectId}/search-tables)
 *   - AspectLinkedSearchTableCreateRequest    (POST /v1/aspects/{aspectId}/linked-search-tables)
 *   - AspectSearchTableUpdateInput            (PUT  /v1/aspects/{aspectId}/search-tables/{id})
 *   - SearchTable                             (GET  /v1/aspects/{aspectId}/search-tables/{id}, and every response)
 *   - VectorIndexInput                        (nested)
 *
 * The aspect id moved from the request body to the URL path — both
 * create requests and the update request now identify the owning
 * aspect through the path parameter, not a `aspectId` body field. The
 * shapes here are the literal JSON payload; the serializer in
 * `src/searchTables/serializer/` is the single place that resolves EDK
 * refs (App, AppField, AiProviderConnector, CloudLink) to the id-strings
 * these requests expect.
 */
export {};
